    if (x === Infinity) return "Inf"; if (x === -Infinity) return "-Inf";
    if (x === 0) return "0";
    const dec = Math.min(15, Math.max(0, 7 - (Math.floor(Math.log10(Math.abs(x))) + 1)));
    let fijo = x.toFixed(dec); if (fijo.includes(".")) fijo = fijo.replace(/\.?0+$/, "");
    let [m, e] = Number(x.toPrecision(7)).toExponential().split("e");
    const ex = Number(e), sci = m + "e" + (ex < 0 ? "-" : "+") + String(Math.abs(ex)).padStart(2, "0");
    const fijoLargo = Math.abs(x) >= 1e15 ? sci : fijo;
    return fijoLargo.length <= sci.length ? fijoLargo : sci;
  }
  function lexer(s) {
    const t = []; let i = 0;
    while (i < s.length) {
      const c = s[i];
      if (c === "#") break;
      if (/\s/.test(c)) { i++; continue; }
      let m;
      if ((m = /^(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?/.exec(s.slice(i)))) { t.push({ k: "num", v: Number(m[0]) }); i += m[0].length; continue; }
      if ((m = /^[A-Za-z.][A-Za-z0-9._]*/.exec(s.slice(i)))) { t.push({ k: "id", v: m[0] }); i += m[0].length; continue; }
      if (s.startsWith("<-", i)) { t.push({ k: "op", v: "<-" }); i += 2; continue; }
      if (s.startsWith("%%", i)) { t.push({ k: "op", v: "%%" }); i += 2; continue; }
      if (s.startsWith("%/%", i)) { t.push({ k: "op", v: "%/%" }); i += 3; continue; }
      if (s.startsWith("**", i)) { t.push({ k: "op", v: "^" }); i += 2; continue; }
      if ("+-*/^(),=;".includes(c)) { t.push({ k: "op", v: c }); i++; continue; }
      if (c === '"' || c === "'") {
        const fin = s.indexOf(c, i + 1);
        if (fin < 0) throw { incompleto: true };
        t.push({ k: "txt", v: s.slice(i + 1, fin) }); i = fin + 1; continue;
      }
      throw { msg: "Error: unexpected input in \"" + s + "\"" };
    }
    return t;
  }
  function evaluar(linea) {
    const t = lexer(linea); let p = 0; const avisos = [];
    const ver = () => t[p], es = v => t[p] && t[p].k === "op" && t[p].v === v;
    const fin = () => { throw { incompleto: true }; };
    function primario() {
      const k = ver(); if (!k) fin();
      if (k.k === "num") { p++; return k.v; }
      if (k.k === "txt") { p++; return k.v; }
      if (es("(")) { p++; const v = expr(); if (!t[p]) fin(); if (!es(")")) throw { msg: "Error: unexpected symbol in \"" + linea + "\"" }; p++; return v; }
      if (k.k === "id") {
        p++;
        if (es("(")) {
          p++; const args = [];
          if (!t[p]) fin();
          if (!es(")")) { for (;;) { args.push(expr()); if (!t[p]) fin(); if (es(",")) { p++; continue; } if (es(")")) break; throw { msg: "Error: unexpected symbol in \"" + linea + "\"" }; } }
          p++;
          const f = funciones[k.v];
          if (!f) throw { msg: "Error in " + k.v + "() : could not find function \"" + k.v + "\"" };
          if (args.length < f[0] || args.length > f[1]) throw { msg: "Error in " + k.v + "(): número de argumentos incorrecto" };
          if (args.some(a => typeof a === "string")) throw { msg: "Error in " + k.v + "(" + JSON.stringify(args[0]) + ") : non-numeric argument to mathematical function" };
          const r = f[2](...args);
          if (Number.isNaN(r) && !args.some(Number.isNaN)) avisos.push("Warning message:\nIn " + k.v + "(" + args.map(formato).join(", ") + ") : NaNs produced");
          return r;
        }
        if (k.v === "pi") return Math.PI;
        if (k.v === "TRUE" || k.v === "T") return 1;
        if (k.v === "FALSE" || k.v === "F") return 0;
        if (k.v === "Inf") return Infinity;
        if (k.v in vars) return vars[k.v];
        throw { msg: "Error: object '" + k.v + "' not found" };
      }
      throw { msg: "Error: unexpected '" + k.v + "' in \"" + linea + "\"" };
    }
    function potencia() { const b = primario(); if (es("^")) { p++; return Math.pow(b, unario()); } return b; }
    function unario() { if (es("-")) { p++; return -unario(); } if (es("+")) { p++; return unario(); } return potencia(); }
    function num(v) { if (typeof v === "string") throw { msg: "Error: non-numeric argument to binary operator" }; return v; }
    function termino() {
      let v = unario();
      while (es("*") || es("/") || es("%%") || es("%/%")) {
        const o = t[p++].v; const w = num(unario()); v = num(v);
        v = o === "*" ? v * w : o === "/" ? v / w : o === "%%" ? v - Math.floor(v / w) * w : Math.floor(v / w);
      }
      return v;
    }
    function suma() { let v = termino(); while (es("+") || es("-")) { const o = t[p++].v; const w = num(termino()); v = num(v); v = o === "+" ? v + w : v - w; } return v; }
    function expr() { return suma(); }
    const salidas = [];
    while (p < t.length) {
      if (es(";")) { p++; continue; }
      let nombre = null;
      if (t[p].k === "id" && t[p + 1] && t[p + 1].k === "op" && (t[p + 1].v === "<-" || t[p + 1].v === "=")) { nombre = t[p].v; p += 2; }
      const v = expr();
      if (p < t.length && !es(";")) throw { msg: "Error: unexpected " + (t[p].k === "num" ? "numeric constant" : "symbol") + " in \"" + linea + "\"" };
      if (nombre) vars[nombre] = v;
      else salidas.push(typeof v === "string" ? '[1] "' + v + '"' : "[1] " + formato(v));
    }
    return { salidas, avisos };
  }
  function mostrarEntorno() {
    const n = Object.keys(vars);
    entorno.textContent = n.length ? "Environment: " + n.map(k => k + " = " + (typeof vars[k] === "string" ? '"' + vars[k] + '"' : formato(vars[k]))).join(", ") : "";
  }
  function ejecutar() {
    const texto = entrada.value;
    escribir((pendiente ? "+ " : "> ") + texto, "c-cmd");
    if (texto.trim()) { historial.push(texto); pos = historial.length; }
    const completa = pendiente ? pendiente + " " + texto : texto;
    entrada.value = "";
    try {
      const r = evaluar(completa);
      r.salidas.forEach(s => escribir(s, "c-sal"));
      r.avisos.forEach(s => escribir(s, "c-err"));
      pendiente = "";
    } catch (e) {
      if (e.incompleto) { pendiente = completa; }
      else { escribir(e.msg || "Error", "c-err"); pendiente = ""; }
    }
    prompt.textContent = pendiente ? "+" : ">";
    mostrarEntorno();
  }
  function cancelar() { if (pendiente || entrada.value) { escribir((pendiente ? "+ " : "> ") + entrada.value, "c-cmd"); } pendiente = ""; entrada.value = ""; prompt.textContent = ">"; }
  entrada.addEventListener("keydown", e => {
    if (e.key === "Enter") { e.preventDefault(); ejecutar(); }
    else if (e.key === "Escape") { e.preventDefault(); cancelar(); }
    else if (e.key === "ArrowUp") { if (pos > 0) { pos--; entrada.value = historial[pos]; } e.preventDefault(); }
    else if (e.key === "ArrowDown") { if (pos < historial.length - 1) { pos++; entrada.value = historial[pos]; } else { pos = historial.length; entrada.value = ""; } e.preventDefault(); }
    else if (e.key === "l" && e.ctrlKey) { e.preventDefault(); pantalla.textContent = ""; }
  });
  raiz.querySelector(".c-esc").addEventListener("click", () => { cancelar(); entrada.focus(); });
  raiz.querySelector(".c-limpiar").addEventListener("click", () => { pantalla.textContent = ""; entrada.focus(); });
  escribir("R simplificado para practicar. Ejemplos: 2 + 3 * 4   sqrt(144)   area <- 30 * 45   area / 10000", "c-info");
})();
</script>
